import 'dart:async';
import 'dart:math';
import 'package:flutter/material.dart';

class LifeCounterPage extends StatefulWidget { const LifeCounterPage({super.key}); @override State<LifeCounterPage> createState()=>_LifeCounterPageState(); }
class _LifeCounterPageState extends State<LifeCounterPage>{
 int _count=4,_start=40,_seconds=0; late List<_P> _p; int? _monarch,_initiative; final List<_Undo> _history=[]; Timer? _timer; bool _running=false,_compactSetup=false;
