 Expanded(child:LayoutBuilder(builder:(context,c){final landscape=c.maxWidth>c.maxHeight;final cols=_count<=2?1:landscape?min(4,_count):2;final ratio=landscape?(_compactSetup?1.45:1.18):(_compactSetup?.88:.76);return GridView.builder(padding:const EdgeInsets.fromLTRB(8,0,8,10),gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:cols,crossAxisSpacing:8,mainAxisSpacing:8,childAspectRatio:ratio),itemCount:_count,itemBuilder:(context,i)=>_tile(i,t));}))]));}
 Widget _tile(int i,ThemeData t){final p=_p[i],cmdMax=p.commander.isEmpty?0:p.commander.reduce(max),lethal=p.life<=0||p.poison>=10||cmdMax>=21;final accent=[t.colorScheme.primary,t.colorScheme.tertiary,t.colorScheme.secondary,t.colorScheme.error][i%4];return Card(clipBehavior:Clip.antiAlias,elevation:lethal?4:1,child:Container(decoration:BoxDecoration(border:Border(top:BorderSide(color:lethal?t.colorScheme.error:accent,width:5))),child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(10,7,6,0),child:Row(children:[Expanded(child:InkWell(onTap:()=>_rename(i),child:Text(p.name,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.w900)))),if(_monarch==i)const Text('👑 '),if(_initiative==i)Icon(Icons.explore_rounded,size:17,color:accent),PopupMenuButton<String>(padding:EdgeInsets.zero,iconSize:20,onSelected:(v)=>_playerMenu(i,v),itemBuilder:(_)=>const[PopupMenuItem(value:'cmd',child:Text('Commander Damage')),PopupMenuItem(value:'monarch',child:Text('Tornar Monarca')),PopupMenuItem(value:'initiative',child:Text('Dar Iniciativa')),PopupMenuItem(value:'rename',child:Text('Editar nome'))])])),Expanded(child:Row(children:[Expanded(child:InkWell(onTap:()=>_life(i,-1),onLongPress:()=>_life(i,-5),child:Center(child:Icon(Icons.remove_rounded,size:42,color:accent)))),Expanded(flex:2,child:FittedBox(fit:BoxFit.scaleDown,child:Text('${p.life}',style:TextStyle(fontSize:88,fontWeight:FontWeight.w900,height:.9,color:lethal?t.colorScheme.error:null)))),Expanded(child:InkWell(onTap:()=>_life(i,1),onLongPress:()=>_life(i,5),child:Center(child:Icon(Icons.add_rounded,size:42,color:accent))))])),Padding(padding:const EdgeInsets.fromLTRB(7,0,7,7),child:Wrap(spacing:5,runSpacing:3,alignment:WrapAlignment.center,children:[ActionChip(label:Text('☠ ${p.poison}'),tooltip:'Poison: toque +1 • segure -1',onPressed:()=>_poison(i,1),onLongPress:()=>_poison(i,-1)),ActionChip(label:Text('Tax ${p.tax}'),tooltip:'Commander Tax: toque +1 • segure -1',onPressed:()=>_tax(i,1),onLongPress:()=>_tax(i,-1)),ActionChip(avatar:const Icon(Icons.shield_outlined,size:15),label:Text(cmdMax>0?'CMD $cmdMax/21':'CMD'),onPressed:()=>_commanderSheet(i))]))])));}
 void _playerMenu(int i,String v){if(v=='cmd')_commanderSheet(i);if(v=='rename')_rename(i);if(v=='monarch')setState(()=>_monarch=_monarch==i?null:i);if(v=='initiative')setState(()=>_initiative=_initiative==i?null:i);}
 Future<void> _commanderSheet(int victim)async{await showModalBottomSheet(context:context,isScrollControlled:true,builder:(context)=>SafeArea(child:Padding(padding:const EdgeInsets.all(18),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Commander Damage em ${_p[victim].name}',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:4),Text('O dano reduz a vida automaticamente. 21 do mesmo comandante é letal.',style:TextStyle(color:Theme.of(context).colorScheme.onSurfaceVariant)),const SizedBox(height:14),...List.generate(_count,(source){if(source==victim)return const SizedBox.shrink();final value=_p[victim].commander[source];return ListTile(contentPadding:EdgeInsets.zero,title:Text(_p[source].name,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:LinearProgressIndicator(value:min(1,value/21)),leading:CircleAvatar(child:Text('${source+1}')),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:(){_cmd(victim,source,-1);Navigator.pop(context);_commanderSheet(victim);},icon:const Icon(Icons.remove_circle_outline_rounded)),SizedBox(width:48,child:Text('$value/21',textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.w900))),IconButton(onPressed:(){_cmd(victim,source,1);Navigator.pop(context);_commanderSheet(victim);},icon:const Icon(Icons.add_circle_outline_rounded))]));})]))));}
